use super::*;

fn test_options() -> StoreOptions {
    StoreOptions {
        slab_size: 16,
        max_extent_bytes: 4,
        chunk_size: 4,
        volume_count: 2,
        persistent_snapshot_path: String::new(),
        persistent_snapshot_flush_on_commit: false,
        persistent_journal_path: String::new(),
        replica_count: 3,
        write_quorum: 2,
        reuse_stale_slab_space: false,
        compaction_fragment_threshold: 2,
        object_manifest_checkpoint_interval: 1,
        object_metadata_checkpoint_interval: 1,
        metadata_route_cache_entries: DEFAULT_METADATA_ROUTE_CACHE_ENTRIES,
        metadata_route_cache_ttl_ms: DEFAULT_METADATA_ROUTE_CACHE_TTL_MS,
        page_read_parallelism: DEFAULT_PAGE_READ_PARALLELISM,
        page_write_parallelism: DEFAULT_PAGE_WRITE_PARALLELISM,
        page_batch_read_parallelism: DEFAULT_PAGE_BATCH_READ_PARALLELISM,
        page_batch_write_parallelism: DEFAULT_PAGE_BATCH_WRITE_PARALLELISM,
        page_batch_discard_parallelism: DEFAULT_PAGE_BATCH_DISCARD_PARALLELISM,
        page_repair_parallelism: DEFAULT_PAGE_REPAIR_PARALLELISM,
        page_chunk_fanout_parallelism: DEFAULT_PAGE_CHUNK_FANOUT_PARALLELISM,
        local_replica_store_parallelism: DEFAULT_LOCAL_REPLICA_STORE_PARALLELISM,
        control_plane_mode: ControlPlaneMode::Auto,
        metaserver_catalog_endpoints: String::new(),
        rootserver_catalog_endpoint: String::new(),
    }
}

fn root_node(node_id: &str, domain: &str, capacity_bytes: u64) -> RootNode {
    RootNode {
        node_id: node_id.to_string(),
        endpoint: format!("{node_id}.matrix.local:9102"),
        service_kind: "chunkserver".to_string(),
        failure_domain: domain.to_string(),
        metadata_eligible: false,
        data_eligible: true,
        gateway_eligible: false,
        metadata_value_bytes: 0,
        capacity_bytes,
        used_bytes: 0,
        committed_bytes: 0,
        draining: false,
        online: true,
        last_heartbeat_ms: 1,
        page_allocator_shard_index: 0,
        page_allocator_shard_count: 1,
        meta_health: RootMetaHealth::default(),
        page_health: RootPageHealth::default(),
        chunk_health: RootChunkHealth::default(),
    }
}

fn pageserver_root_node(
    node_id: &str,
    domain: &str,
    shard_index: u64,
    shard_count: u64,
) -> RootNode {
    RootNode {
        node_id: node_id.to_string(),
        endpoint: format!("{node_id}.matrix.local:9101"),
        service_kind: "blockserver".to_string(),
        failure_domain: domain.to_string(),
        metadata_eligible: false,
        data_eligible: true,
        gateway_eligible: false,
        metadata_value_bytes: 0,
        capacity_bytes: 1,
        used_bytes: 0,
        committed_bytes: 0,
        draining: false,
        online: true,
        last_heartbeat_ms: 1,
        page_allocator_shard_index: shard_index,
        page_allocator_shard_count: shard_count,
        meta_health: RootMetaHealth::default(),
        page_health: RootPageHealth {
            ready: true,
            read_ready: true,
            route_control_checksum: format!("route-{node_id}-{shard_index}-{shard_count}"),
            route_control_commit_index: shard_index.saturating_add(1),
            chunk_endpoint_count: 3,
            writable_chunk_endpoint_count: 2,
            healthy_chunk_endpoint_count: 3,
            raft_writable_chunk_endpoint_count: 2,
            raft_readable_chunk_endpoint_count: 3,
            capacity_ready_writable_chunk_endpoint_count: 2,
            quarantined_chunk_replicas: 0,
            chunk_capacity_bytes: 192,
            chunk_capacity_free_bytes: 128,
            allocation_receipt_count: shard_index.saturating_add(3),
            batch_allocation_receipt_count: shard_index.saturating_add(5),
            release_allocation_receipt_count: shard_index.saturating_add(7),
            write_receipt_count: shard_index.saturating_add(11),
            batch_write_receipt_count: shard_index.saturating_add(13),
            discard_receipt_count: shard_index.saturating_add(17),
            batch_discard_receipt_count: shard_index.saturating_add(19),
            ..RootPageHealth::default()
        },
        chunk_health: RootChunkHealth::default(),
    }
}

fn metaserver_root_node(
    node_id: &str,
    domain: &str,
    readable: bool,
    writable: bool,
    topology_checksum: &str,
    topology_epoch: u64,
) -> RootNode {
    let mut meta_health = RootMetaHealth::default();
    meta_health.control_proof.state_format = "MOSRSMETA-CONTROL5".to_string();
    meta_health.control_proof.state_bytes = 128;
    meta_health.control_proof.state_checksum = format!("{node_id}-proof");
    meta_health.control_proof.read_ready = readable;
    meta_health.control_proof.write_ready = writable;
    meta_health.control_proof.commit_bounds_valid = true;
    meta_health.control_proof.topology_checksum = topology_checksum.to_string();
    meta_health.control_proof.session_checksum = "sessions-a".to_string();
    meta_health.control_proof.state_fingerprint = format!("{node_id}-state");
    meta_health.control_proof.raft_membership_epoch = topology_epoch;
    meta_health.control_proof.raft_membership_receipt_count = 3;
    meta_health.control_proof.metadata_replication_quorum = 1;
    meta_health.control_proof.metadata_replication_acks = 1;
    meta_health.control_proof.last_applied_mutation_commit_index = topology_epoch;
    meta_health.control_proof.last_applied_mutation_time_ms = 10;
    meta_health.control_proof.last_applied_mutation_age_ms = 1;
    meta_health.control_proof.apply_commit_lag = 0;
    meta_health.control_proof.apply_caught_up = true;
    meta_health.control_proof.requested_read_fence = topology_epoch;
    meta_health.control_proof.safe_read_fence = topology_epoch;
    meta_health.control_proof.read_fence_covered = readable;
    meta_health.control_proof.read_fence_commit_lag = 0;
    meta_health.control_proof.read_fence_read_index_lag = 0;
    meta_health.control_proof.read_fence_applied_lag = 0;
    meta_health.route_cache.topology_epoch = topology_epoch;
    meta_health.route_cache.topology_checksum = topology_checksum.to_string();
    meta_health.route_cache.shard_topology_checksum = topology_checksum.to_string();
    meta_health.route_cache.session_checksum = "sessions-a".to_string();
    meta_health.route_cache.fresh = readable;
    RootNode {
        node_id: node_id.to_string(),
        endpoint: format!("{node_id}.matrix.local:9105"),
        service_kind: "metaserver".to_string(),
        failure_domain: domain.to_string(),
        metadata_eligible: true,
        data_eligible: false,
        gateway_eligible: false,
        metadata_value_bytes: meta_health.control_proof.state_bytes,
        capacity_bytes: 0,
        used_bytes: 0,
        committed_bytes: 0,
        draining: false,
        online: true,
        last_heartbeat_ms: 1,
        page_allocator_shard_index: 0,
        page_allocator_shard_count: 1,
        meta_health,
        page_health: RootPageHealth::default(),
        chunk_health: RootChunkHealth::default(),
    }
}

fn tags(items: &[(&str, &str)]) -> BTreeMap<String, String> {
    items
        .iter()
        .map(|(key, value)| (key.to_string(), value.to_string()))
        .collect()
}

fn assert_snapshot_progress(
    progress: &SnapshotInstallProgress,
    active: bool,
    next_offset: u64,
    total_bytes: u64,
    full_checksum: &str,
) {
    assert!(progress.resume_supported);
    assert_eq!(progress.stream_active, active);
    assert_eq!(progress.next_offset, next_offset);
    assert_eq!(progress.total_bytes, total_bytes);
    assert_eq!(
        progress.remaining_bytes,
        total_bytes.saturating_sub(next_offset)
    );
    assert_eq!(progress.full_checksum, full_checksum);
    if total_bytes == 0 || full_checksum.is_empty() {
        assert!(progress.stream_id.is_empty());
    } else {
        assert!(!progress.stream_id.is_empty());
    }
}

