#[test]
fn append_object_extends_existing_blob_without_staling_old_extents() {
    let mut store = MatrixObjectStore::new(test_options()).unwrap();
    store.create_bucket("bucket").unwrap();
    let first = store
        .append_object("bucket", "wal", b"abc".to_vec(), "application/octet-stream")
        .unwrap();
    assert_eq!(first.length, 3);
    assert_eq!(first.extents.len(), 1);

    let second = store
        .append_object(
            "bucket",
            "wal",
            b"defghi".to_vec(),
            "application/octet-stream",
        )
        .unwrap();
    assert_eq!(second.length, 9);
    assert!(
        second.extents.len() > first.extents.len(),
        "append should add new extents instead of rewriting the whole object"
    );
    assert_eq!(second.extents[0], first.extents[0]);
    assert_eq!(
        store.get_object("bucket", "wal").unwrap().data,
        b"abcdefghi"
    );
    let first_slab = store
        .slabs
        .get(&first.extents[0].slab_id)
        .expect("first append segment remains present");
    assert_eq!(first_slab.stale_bytes, 0);
}

#[test]
fn persistent_snapshot_reopens_append_blob_offsets() {
    let root = std::env::temp_dir().join(format!(
        "matrixobjectstore-persistent-{}-{}",
        std::process::id(),
        now_millis()
    ));
    let snapshot_path = root.join("store.snapshot");
    let snapshot_path_string = snapshot_path.to_string_lossy().to_string();
    let mut options = test_options();
    options.persistent_snapshot_path = snapshot_path_string;
    options.persistent_snapshot_flush_on_commit = false;
    {
        let mut store = MatrixObjectStore::new(options.clone()).unwrap();
        store.create_bucket("bucket").unwrap();
        let first = store
            .append_object("bucket", "wal", b"abc".to_vec(), "application/octet-stream")
            .unwrap();
        let second = store
            .append_object(
                "bucket",
                "wal",
                b"defg".to_vec(),
                "application/octet-stream",
            )
            .unwrap();
        assert_eq!(first.length, 3);
        assert_eq!(second.length, 7);
        store.flush_persistent_snapshot().unwrap();
        assert!(snapshot_path.exists());
    }
    let reopened = MatrixObjectStore::new(options).unwrap();
    let object = reopened.get_object("bucket", "wal").unwrap();
    assert_eq!(object.data, b"abcdefg");
    assert_eq!(object.metadata.length, 7);
    assert_eq!(object.metadata.extents.len(), 2);
    assert_eq!(object.metadata.extents[0].offset, 0);
    assert_eq!(object.metadata.extents[0].length, 3);
    assert_eq!(object.metadata.extents[1].offset, 3);
    assert_eq!(object.metadata.extents[1].length, 4);
    let _ = std::fs::remove_dir_all(root);
}

