    assert_eq!(first.repair_reason, "blockserver_repair_ready_more");

    let second = page
        .repair_audited_chunk_replicas(first.audit.next_marker.as_ref(), 10, 0)
        .unwrap();
    assert_eq!(second.candidate_chunks, 1);
