#[test]
fn raft_backed_store_exports_and_installs_chunked_snapshots() {
    let mut stale_raft = InMemoryRustRaft::new(1).unwrap();
    stale_raft
        .append(ObjectCommand::CreateBucket {
            bucket: "ahead".to_string(),
        })
        .unwrap();
    let stale_store = MatrixObjectStore::new(test_options()).unwrap();
    let stale = RaftBackedObjectStore::new(stale_raft, stale_store);
    let stale_err = stale
        .export_snapshot_chunk_with_read_proof_linearizable(0, 128, 10)
        .unwrap_err();
    assert!(stale_err
        .to_string()
        .contains("snapshot export metadata control read index is not satisfied"));

    let raft = InMemoryRustRaft::new(1).unwrap();
    let store = MatrixObjectStore::new(test_options()).unwrap();
    let mut replicated = RaftBackedObjectStore::new(raft, store);
    replicated
        .propose(ObjectCommand::PutObject {
            bucket: "bucket".to_string(),
            key: "snapshot-object".to_string(),
            data: vec![7; 192],
            content_type: "application/octet-stream".to_string(),
            update_time_ms: 1,
            options: PutOptions::default(),
        })
        .unwrap();

    let mut follower = RaftBackedObjectStore::new(
        InMemoryRustRaft::new(1).unwrap(),
        MatrixObjectStore::new(test_options()).unwrap(),
    );
    let mut assembler = StoreSnapshotChunkAssembler::default();
    let mut offset = 0;
    let mut chunk_count = 0;
    loop {
        let proven_chunk = replicated
            .export_snapshot_chunk_with_read_proof_linearizable(offset, 128, 20)
            .unwrap();
        assert_eq!(
            proven_chunk.proof.requested_read_index,
            replicated.raft_commit_index()
        );
        assert_eq!(
            proven_chunk.proof.consensus_read_index,
            replicated.raft_commit_index()
        );
        assert_eq!(
            proven_chunk.proof.metadata_commit_index,
            replicated.raft_commit_index()
        );
        let chunk = proven_chunk.value;
        assert_eq!(chunk.last_applied_index, replicated.raft_commit_index());
        assert_eq!(chunk.term, 1);
        let expected_next = chunk.offset.saturating_add(chunk.payload.len() as u64);
        let eof = chunk.eof;
        let progress = follower.push_snapshot_chunk(&mut assembler, chunk).unwrap();
        if eof {
            assert!(!progress.stream_active);
        } else {
            assert!(progress.stream_active);
            assert_eq!(progress.next_offset, expected_next);
        }
        offset = expected_next;
        chunk_count += 1;
        if eof {
            break;
        }
    }
    assert!(chunk_count > 1);
    assert_eq!(
        follower.store().last_applied_index(),
        replicated.raft_commit_index()
    );
    assert_eq!(
        follower
            .store()
            .get_object("bucket", "snapshot-object")
            .unwrap()
            .data,
        vec![7; 192]
    );
    let restored_record = follower
        .store()
        .metadata_record("object/bucket/snapshot-object")
        .unwrap();
    assert!(restored_record.value.contains("version=1"));
    assert!(restored_record.value.contains("length=192"));
}

#[test]
fn raft_apply_retries_exact_entry_and_rejects_conflict() {
    let mut raft = InMemoryRustRaft::new(7).unwrap();
    let entry = raft
        .append(ObjectCommand::PutObject {
            bucket: "bucket".to_string(),
            key: "object".to_string(),
            data: b"retry-safe".to_vec(),
            content_type: "text/plain".to_string(),
            update_time_ms: 1,
            options: PutOptions::default(),
        })
        .unwrap();
    let mut follower = MatrixObjectStore::new(test_options()).unwrap();
    let first = follower.apply_raft_entry(&entry).unwrap();
    let retry = follower.apply_raft_entry(&entry).unwrap();
    assert_eq!(retry, first);
    assert_eq!(follower.last_applied_index(), 1);
    let mut conflicting = entry.clone();
    conflicting.command = ObjectCommand::PutObject {
        bucket: "bucket".to_string(),
        key: "object".to_string(),
        data: b"different".to_vec(),
        content_type: "text/plain".to_string(),
        update_time_ms: 1,
        options: PutOptions::default(),
    };
    assert!(matches!(
        follower.apply_raft_entry(&conflicting),
        Err(ObjectError::InvalidArgument(_))
    ));

    let snapshot = follower.export_snapshot().unwrap();
    snapshot.validate().unwrap();
    let mut restored = MatrixObjectStore::new(test_options()).unwrap();
    restored.install_snapshot(snapshot).unwrap();
    let restored_retry = restored.apply_raft_entry(&entry).unwrap();
    assert_eq!(restored_retry, first);
}

