#[test]
fn raft_backed_store_replays_batch_copy_object_commands() {
    let raft = InMemoryRustRaft::new(1).unwrap();
    let store = MatrixObjectStore::new(test_options()).unwrap();
    let mut replicated = RaftBackedObjectStore::new(raft, store);
    replicated
        .propose(ObjectCommand::PutObject {
            bucket: "bucket".to_string(),
            key: "source-a".to_string(),
            data: b"alpha".to_vec(),
            content_type: "text/plain".to_string(),
            update_time_ms: 1,
            options: PutOptions::default(),
        })
        .unwrap();
    replicated
        .propose(ObjectCommand::PutObject {
            bucket: "bucket".to_string(),
            key: "source-b".to_string(),
            data: b"bravo".to_vec(),
            content_type: "text/plain".to_string(),
            update_time_ms: 2,
            options: PutOptions::default(),
        })
        .unwrap();

    let route_checksum = replicated
        .store
        .page_service
        .route_control_proof()
        .state_checksum;
    let local_report = replicated
        .store
        .batch_copy_objects_fenced(
            vec![ObjectCopyRequest {
                source_bucket: "bucket".to_string(),
                source_key: "source-a".to_string(),
                source_version: None,
                destination_bucket: "copy".to_string(),
                destination_key: "local-proof".to_string(),
                content_type: Some("application/local-copy".to_string()),
                options: PutOptions::default(),
            }],
            4,
            1024,
            4,
            Some(&route_checksum),
        )
        .unwrap();
    assert_eq!(local_report.copied_objects, 1);
    assert_eq!(local_report.expected_route_control_checksum, route_checksum);
    assert_eq!(
        local_report.route_control_proof.state_checksum,
        local_report.expected_route_control_checksum
    );
    assert!(matches!(
        replicated.store.batch_copy_objects_fenced(
            Vec::new(),
            4,
            1024,
            5,
            Some("stale-route-checksum"),
        ),
        Err(ObjectError::PreconditionFailed(_))
    ));

    let metadata = replicated
        .propose_batch_copy_objects(
            vec![
                ObjectCopyRequest {
                    source_bucket: "bucket".to_string(),
                    source_key: "source-a".to_string(),
                    source_version: None,
                    destination_bucket: "copy".to_string(),
                    destination_key: "source-a".to_string(),
                    content_type: Some("application/copied".to_string()),
                    options: PutOptions::default(),
                },
                ObjectCopyRequest {
                    source_bucket: "bucket".to_string(),
                    source_key: "source-b".to_string(),
                    source_version: None,
                    destination_bucket: "copy".to_string(),
                    destination_key: "source-b".to_string(),
                    content_type: None,
                    options: PutOptions::default(),
                },
                ObjectCopyRequest {
                    source_bucket: "bucket".to_string(),
                    source_key: "missing".to_string(),
                    source_version: None,
                    destination_bucket: "copy".to_string(),
                    destination_key: "missing".to_string(),
                    content_type: None,
                    options: PutOptions::default(),
                },
            ],
            8,
            1024,
            3,
        )
        .unwrap();

    assert_eq!(metadata.content_type, "objectstore/batch-copy");
    assert_eq!(metadata.version, 2);
    assert_eq!(metadata.length, 1);
    assert_eq!(metadata.update_time_ms, 10);
    assert_eq!(replicated.raft_commit_index(), 3);

    let mut follower = MatrixObjectStore::new(test_options()).unwrap();
    replicated.replay_into(&mut follower).unwrap();
    let copy_a = follower.get_object("copy", "source-a").unwrap();
    assert_eq!(copy_a.data, b"alpha".to_vec());
    assert_eq!(copy_a.metadata.content_type, "application/copied");
    assert_eq!(
        follower.get_object("copy", "source-b").unwrap().data,
        b"bravo".to_vec()
    );
    assert!(follower.get_object("copy", "missing").is_err());
    assert_eq!(follower.last_applied_index(), 3);
}

#[test]
