#[test]
fn raft_backed_store_replays_idempotent_generic_metaserver_batches() {
    let raft = InMemoryRustRaft::new(1).unwrap();
    let store = MatrixObjectStore::new(test_options()).unwrap();
    let mut replicated = RaftBackedObjectStore::new(raft, store);
    let mutations = vec![
        MetadataMutation {
            key: "object/raft-meta-generic/a".to_string().into(),
            value: "etag=a length=1".to_string(),
            expected_version: 0,
            delete: false,
        },
        MetadataMutation {
            key: "object/raft-meta-generic/b".to_string().into(),
            value: "etag=b length=2".to_string(),
            expected_version: 0,
            delete: false,
        },
    ];
    let first = replicated
        .propose_commit_metadata_batch_idempotent(
            mutations.clone(),
            None,
            None,
            10,
            "raft-meta-batch-a",
        )
        .unwrap();
    assert_eq!(first.content_type, "metaserver/idempotent-batch");
    assert_eq!(first.version, 2);
    assert_eq!(first.length, 0);
    let retry = replicated
        .propose_commit_metadata_batch_idempotent(
            mutations.clone(),
            None,
            None,
            10,
            "raft-meta-batch-a",
        )
        .unwrap();
    assert_eq!(retry.content_type, "metaserver/idempotent-batch");
    assert_eq!(retry.version, 2);
    assert_eq!(retry.length, 1);
    assert!(matches!(
        replicated.propose_commit_metadata_batch_idempotent(
            vec![MetadataMutation {
                key: "object/raft-meta-generic/a".to_string().into(),
                value: "changed".to_string(),
                expected_version: 0,
                delete: false,
            }],
            None,
            None,
            10,
            "raft-meta-batch-a",
        ),
        Err(ObjectError::PreconditionFailed(_))
    ));
    assert_eq!(replicated.raft_commit_index(), 2);

    let mut follower = MatrixObjectStore::new(test_options()).unwrap();
    replicated.replay_into(&mut follower).unwrap();
    assert_eq!(
        follower
            .metadata_record("object/raft-meta-generic/a")
            .unwrap()
            .version,
        1
    );
    assert_eq!(follower.last_applied_index(), 2);
    let snapshot = follower.export_snapshot().unwrap();
    assert_eq!(snapshot.meta_snapshot.batch_request_receipts.len(), 1);
    let mut restored = MatrixObjectStore::new(test_options()).unwrap();
    restored.install_snapshot(snapshot).unwrap();
    let (records, restored_retry) = restored
        .commit_metadata_batch_idempotent(mutations, None, None, 10, "raft-meta-batch-a")
        .unwrap();
    assert!(restored_retry.deduped);
    assert_eq!(records.len(), 2);
    assert_eq!(records[0].version, 1);
}

#[test]
fn raft_backed_store_applies_prepared_metaserver_batches() {
    let raft = InMemoryRustRaft::new(1).unwrap();
    let store = MatrixObjectStore::new(test_options()).unwrap();
    let mut replicated = RaftBackedObjectStore::new(raft, store);
    let mutations = vec![MetadataMutation {
        key: "object/prepared-meta/a".to_string().into(),
        value: "etag=prepared length=1".to_string(),
        expected_version: 0,
        delete: false,
    }];
    let prepared = replicated
        .prepare_commit_metadata_batch_raft_entry(
            mutations.clone(),
            None,
            None,
            10,
            "prepared-meta-batch-a",
        )
        .unwrap();
    assert_eq!(prepared.expected_previous_commit_index, 0);
    assert_eq!(prepared.prepared_commit_index, 1);
    assert_eq!(prepared.images.len(), 1);
    assert_eq!(prepared.images[0].version, 1);
    assert_eq!(prepared.images[0].value, "etag=prepared length=1".into());
    assert!(!prepared.request_checksum.is_empty());
    assert!(!prepared.metadata_control_proof_checksum.is_empty());
    assert_eq!(prepared.metadata_control_proof_now_ms, 10);
    assert!(!prepared.raft_entry_checksum.is_empty());
    assert!(replicated
        .store()
        .metadata_record("object/prepared-meta/a")
        .is_err());

    let mut tampered = prepared.clone();
    tampered.raft_entry_checksum = "etag:bad".to_string();
    assert!(matches!(
        replicated
            .store()
            .clone()
            .apply_command(ObjectCommand::ApplyPreparedMetaBatch { prepared: tampered }),
        Err(ObjectError::Corruption(_))
    ));

    let mut stale_proof = prepared.clone();
    stale_proof.metadata_control_proof_checksum = "stale-metadata-proof".to_string();
    stale_proof.raft_entry_checksum = prepared_metadata_batch_checksum(&stale_proof);
    assert!(matches!(
        replicated
            .store()
            .clone()
            .apply_command(ObjectCommand::ApplyPreparedMetaBatch {
                prepared: stale_proof.clone()
            }),
        Err(ObjectError::PreconditionFailed(_))
    ));
    assert!(matches!(
        replicated.propose_prepared_metadata_batch(stale_proof),
        Err(ObjectError::PreconditionFailed(_))
    ));

    let applied = replicated
        .propose_prepared_metadata_batch(prepared.clone())
        .unwrap();
    assert_eq!(applied.content_type, "metaserver/prepared-batch");
    assert_eq!(applied.version, 1);
    assert_eq!(replicated.raft_commit_index(), 1);
    assert_eq!(
        replicated
            .store()
            .metadata_record("object/prepared-meta/a")
            .unwrap()
            .value,
        "etag=prepared length=1".into()
    );

    let mut follower = MatrixObjectStore::new(test_options()).unwrap();
    replicated.replay_into(&mut follower).unwrap();
    assert_eq!(follower.last_applied_index(), 1);
    let record = follower.metadata_record("object/prepared-meta/a").unwrap();
    assert_eq!(record.version, 1);
    assert_eq!(record.value, "etag=prepared length=1".into());
    assert_eq!(
        follower
            .export_snapshot().unwrap()
            .meta_snapshot
            .batch_request_receipts
            .get("prepared-meta-batch-a")
            .unwrap()
            .request_checksum,
        prepared.request_checksum
    );

    let deduped = replicated
        .propose_commit_metadata_batch_prepared(mutations, None, None, 10, "prepared-meta-batch-a")
        .unwrap();
    assert_eq!(deduped.content_type, "metaserver/prepared-batch");
    assert_eq!(deduped.length, 1);
    assert_eq!(replicated.raft_commit_index(), 2);
}

