#[test]
fn raft_backed_store_applies_prepared_metaserver_change_checkpoints() {
    let raft = InMemoryRustRaft::new(1).unwrap();
    let store = MatrixObjectStore::new(test_options()).unwrap();
    let mut replicated = RaftBackedObjectStore::new(raft, store);
    replicated
        .propose_commit_metadata_batch_prepared(
            vec![MetadataMutation {
                key: "object/prepared-checkpoint/a".to_string().into(),
                value: "etag=prepared-checkpoint length=1".to_string(),
                expected_version: 0,
                delete: false,
            }],
            None,
            None,
            10,
            "prepared-checkpoint-write-a",
        )
        .unwrap();
    assert_eq!(replicated.raft_commit_index(), 1);
    let changes = replicated
        .store()
        .page_metadata_changes("object/prepared-checkpoint/", 0, 10, 0)
        .unwrap();
    assert_eq!(changes.changes.len(), 1);
    let checkpoint = MetadataChangeCheckpoint {
        consumer_id: "prepared-checkpoint-consumer".to_string(),
        prefix: "object/prepared-checkpoint/".to_string(),
        after_change_sequence: changes.changes[0].sequence,
        after_commit_index: changes.changes[0].commit_index,
        update_time_ms: 20,
        owner: "meta-owner-a".to_string(),
        note: "prepared checkpoint consumed".to_string(),
    };
    let prepared = replicated
        .prepare_commit_meta_change_checkpoint_raft_entry(
            checkpoint.clone(),
            "prepared-change-checkpoint-a",
        )
        .unwrap();
    assert_eq!(prepared.expected_previous_commit_index, 1);
    assert_eq!(prepared.prepared_commit_index, 2);
    assert_eq!(prepared.checkpoint, checkpoint);
    assert!(!prepared.request_checksum.is_empty());
    assert!(!prepared.raft_entry_checksum.is_empty());
    assert!(replicated
        .store()
        .metadata_change_checkpoint(
            "prepared-checkpoint-consumer",
            "object/prepared-checkpoint/",
        )
        .is_err());

    let mut tampered = prepared.clone();
    tampered.checkpoint.note = "tampered".to_string();
    assert!(matches!(
        replicated
            .store()
            .clone()
            .apply_command(ObjectCommand::ApplyPreparedMetaChangeCheckpoint { prepared: tampered }),
        Err(ObjectError::Corruption(_))
    ));

    let applied = replicated
        .propose_prepared_meta_change_checkpoint(prepared.clone())
        .unwrap();
    assert_eq!(
        applied.content_type,
        "metaserver/prepared-change-checkpoint"
    );
    assert_eq!(applied.version, checkpoint.after_commit_index);
    assert_eq!(replicated.raft_commit_index(), 2);
    let stored = replicated
        .store()
        .metadata_change_checkpoint(
            "prepared-checkpoint-consumer",
            "object/prepared-checkpoint/",
        )
        .unwrap();
    assert_eq!(stored.note, "prepared checkpoint consumed");

    let mut follower = MatrixObjectStore::new(test_options()).unwrap();
    replicated.replay_into(&mut follower).unwrap();
    assert_eq!(follower.last_applied_index(), 2);
    let follower_checkpoint = follower
        .metadata_change_checkpoint(
            "prepared-checkpoint-consumer",
            "object/prepared-checkpoint/",
        )
        .unwrap();
    assert_eq!(follower_checkpoint, checkpoint);
}

#[test]
fn raft_backed_store_applies_prepared_metaserver_changefeed_compaction() {
    let raft = InMemoryRustRaft::new(1).unwrap();
    let store = MatrixObjectStore::new(test_options()).unwrap();
    let mut replicated = RaftBackedObjectStore::new(raft, store);
    replicated
        .propose_commit_metadata_batch_prepared(
            vec![
                MetadataMutation {
                    key: "object/prepared-changefeed/a".to_string().into(),
                    value: "etag=prepared-changefeed-a length=1".to_string(),
                    expected_version: 0,
                    delete: false,
                },
                MetadataMutation {
                    key: "object/prepared-changefeed/b".to_string().into(),
                    value: "etag=prepared-changefeed-b length=1".to_string(),
                    expected_version: 0,
                    delete: false,
                },
            ],
            None,
            None,
            10,
            "prepared-changefeed-write-a",
        )
        .unwrap();
    let changes = replicated
        .store()
        .page_metadata_changes("object/prepared-changefeed/", 0, 10, 0)
        .unwrap();
    assert_eq!(changes.changes.len(), 2);
    replicated
        .propose_commit_meta_change_checkpoint_prepared(
            MetadataChangeCheckpoint {
                consumer_id: "prepared-changefeed-consumer".to_string(),
                prefix: "object/prepared-changefeed/".to_string(),
                after_change_sequence: changes.changes[1].sequence,
                after_commit_index: changes.changes[1].commit_index,
                update_time_ms: 20,
                owner: "meta-owner-a".to_string(),
                note: "prepared changefeed consumed".to_string(),
            },
            "prepared-changefeed-checkpoint-a",
        )
        .unwrap();

    let proven_prepared = replicated
        .prepare_compact_meta_changefeed_raft_entry_with_read_proof_linearizable(
            "object/prepared-changefeed/",
            1,
            30,
        )
        .unwrap();
    assert_eq!(proven_prepared.proof.requested_read_index, 2);
    assert_eq!(proven_prepared.proof.metadata_commit_index, 2);
    let prepared = proven_prepared.value;
    assert_eq!(prepared.expected_previous_commit_index, 2);
    assert_eq!(prepared.prepared_commit_index, 3);
    assert_eq!(prepared.report.compacted_changes, 1);
    assert_eq!(prepared.compacted.len(), 1);
    assert_eq!(prepared.compacted[0].key, "object/prepared-changefeed/a");
    assert!(!prepared.request_checksum.is_empty());
    assert!(!prepared.raft_entry_checksum.is_empty());

    let mut tampered = prepared.clone();
    tampered.compacted[0].key = "object/prepared-changefeed/tampered".to_string().into();
    assert!(matches!(
        replicated.store().clone().apply_command(
            ObjectCommand::ApplyPreparedMetaChangefeedCompaction { prepared: tampered }
        ),
        Err(ObjectError::Corruption(_))
    ));

    let applied = replicated
        .propose_prepared_meta_changefeed_compaction(prepared.clone())
        .unwrap();
    assert_eq!(
        applied.content_type,
        "metaserver/prepared-changefeed-compact"
    );
    assert_eq!(applied.length, 1);
    assert_eq!(replicated.raft_commit_index(), 3);
    let remaining = replicated
        .store()
        .page_metadata_changes("object/prepared-changefeed/", 0, 10, 0)
        .unwrap();
    assert_eq!(remaining.changes.len(), 1);
    assert_eq!(remaining.changes[0].key, "object/prepared-changefeed/b");

    let mut follower = MatrixObjectStore::new(test_options()).unwrap();
    replicated.replay_into(&mut follower).unwrap();
    assert_eq!(follower.last_applied_index(), 3);
    let follower_remaining = follower
        .page_metadata_changes("object/prepared-changefeed/", 0, 10, 0)
        .unwrap();
    assert_eq!(follower_remaining.changes, remaining.changes);
}

#[test]
fn raft_backed_store_applies_prepared_metaserver_transactions() {
    let raft = InMemoryRustRaft::new(1).unwrap();
    let store = MatrixObjectStore::new(test_options()).unwrap();
    let mut replicated = RaftBackedObjectStore::new(raft, store);
    let mutations = vec![MetadataMutation {
        key: "object/prepared-txn/a".to_string().into(),
        value: "etag=prepared-txn length=1".to_string(),
        expected_version: 0,
        delete: false,
    }];

    let prepared_begin = replicated
        .prepare_metadata_transaction_raft_entry(
            "begin",
            "txn-prepared-a",
            "owner-a",
            100,
            mutations.clone(),
            10,
            "prepared-txn-begin-a",
        )
        .unwrap();
    assert_eq!(prepared_begin.expected_previous_commit_index, 0);
    assert_eq!(prepared_begin.prepared_commit_index, 1);
    assert_eq!(prepared_begin.receipt.operation, "begin");
    assert_eq!(prepared_begin.receipt.transaction.state, "pending");
    assert!(!prepared_begin.receipt.request_checksum.is_empty());
    assert!(!prepared_begin.metadata_control_proof_checksum.is_empty());
    assert_eq!(prepared_begin.metadata_control_proof_now_ms, 10);
    assert!(!prepared_begin.raft_entry_checksum.is_empty());
    assert!(replicated
        .store()
        .metadata_transaction("txn-prepared-a")
        .is_err());

    let mut tampered = prepared_begin.clone();
    tampered.raft_entry_checksum = "etag:bad".to_string();
    assert!(matches!(
        replicated
            .store()
            .clone()
            .apply_command(ObjectCommand::ApplyPreparedMetaTransaction { prepared: tampered }),
        Err(ObjectError::Corruption(_))
    ));

    let mut stale_proof = prepared_begin.clone();
    stale_proof.metadata_control_proof_checksum = "stale-metadata-proof".to_string();
    stale_proof.raft_entry_checksum = prepared_metadata_transaction_checksum(&stale_proof);
    assert!(matches!(
        replicated
            .store()
            .clone()
            .apply_command(ObjectCommand::ApplyPreparedMetaTransaction {
                prepared: stale_proof.clone()
            }),
        Err(ObjectError::PreconditionFailed(_))
    ));
    assert!(matches!(
        replicated.propose_prepared_metadata_transaction(stale_proof),
        Err(ObjectError::PreconditionFailed(_))
    ));

    let applied_begin = replicated
        .propose_prepared_metadata_transaction(prepared_begin.clone())
        .unwrap();
    assert_eq!(
        applied_begin.content_type,
        "metaserver/prepared-transaction"
    );
    assert_eq!(replicated.raft_commit_index(), 1);
    assert_eq!(
        replicated
            .store()
            .metadata_transaction("txn-prepared-a")
            .unwrap()
            .state,
        "pending"
    );

    let applied_commit = replicated
        .propose_commit_meta_transaction_prepared(
            "txn-prepared-a",
            "owner-a",
            20,
            "prepared-txn-commit-a",
        )
        .unwrap();
    assert_eq!(
        applied_commit.content_type,
        "metaserver/prepared-transaction"
    );
    assert_eq!(applied_commit.version, 2);
    assert_eq!(
        replicated
            .store()
            .metadata_record("object/prepared-txn/a")
            .unwrap()
            .value,
        "etag=prepared-txn length=1".into()
    );
    assert_eq!(
        replicated
            .store()
            .metadata_transaction("txn-prepared-a")
            .unwrap()
            .state,
        "committed"
    );
    let (mutation_receipts, receipt_readiness) = replicated
        .list_metadata_mutation_receipts_linearizable(None, 10, None, None, None, None, 4096, 25)
        .unwrap();
    assert_eq!(receipt_readiness.reason, "ready");
    assert_eq!(mutation_receipts.total_receipt_count, 2);
    assert_eq!(mutation_receipts.matched_count, 2);
    assert!(mutation_receipts.receipts.iter().any(|receipt| {
        receipt.method == "BeginMetaTransaction"
            && receipt.idempotency_key == "prepared-txn-begin-a"
    }));
    let (commit_receipts, _) = replicated
        .list_metadata_mutation_receipts_linearizable(
            None,
            10,
            Some("CommitMetaTransaction"),
            None,
            Some(false),
            Some("object/prepared-txn/"),
            4096,
            25,
        )
        .unwrap();
    assert_eq!(commit_receipts.receipt_count, 1);
    assert_eq!(
        commit_receipts.receipts[0].idempotency_key,
        "prepared-txn-commit-a"
    );
    assert_eq!(
        commit_receipts.receipts[0].record_keys,
        vec!["object/prepared-txn/a"]
    );
    let checksum = commit_receipts.receipts[0].request_checksum.clone();
    let (checksum_receipts, _) = replicated
        .list_metadata_mutation_receipts_linearizable(
            None,
            10,
            None,
            Some(&checksum),
            None,
            None,
            4096,
            25,
        )
        .unwrap();
    assert_eq!(checksum_receipts.receipt_count, 1);
    assert_eq!(checksum_receipts.receipts[0].request_checksum, checksum);
    assert!(matches!(
        replicated
            .list_metadata_mutation_receipts_linearizable(None, 10, None, None, None, None, 1, 25),
        Err(ObjectError::InvalidArgument(_))
    ));

    let mut follower = MatrixObjectStore::new(test_options()).unwrap();
    replicated.replay_into(&mut follower).unwrap();
    assert_eq!(follower.last_applied_index(), 2);
    assert_eq!(
        follower
            .metadata_record("object/prepared-txn/a")
            .unwrap()
            .version,
        1
    );
    assert_eq!(
        follower
            .export_snapshot().unwrap()
            .meta_snapshot
            .transaction_receipts
            .get("prepared-txn-commit-a")
            .unwrap()
            .operation,
        "commit"
    );
    let follower_receipts = follower
        .list_metadata_mutation_receipts(
            None,
            10,
            Some("CommitMetaTransaction"),
            None,
            None,
            Some("object/prepared-txn/"),
            4096,
        )
        .unwrap();
    assert_eq!(follower_receipts.receipt_count, 1);
    assert_eq!(
        follower_receipts.receipts[0].idempotency_key,
        "prepared-txn-commit-a"
    );

    let deduped = replicated
        .propose_commit_meta_transaction_prepared(
            "txn-prepared-a",
            "owner-a",
            20,
            "prepared-txn-commit-a",
        )
        .unwrap();
    assert_eq!(
        deduped.content_type,
        "metaserver/prepared-transaction-deduped"
    );
    assert_eq!(deduped.length, 1);
    assert_eq!(replicated.raft_commit_index(), 3);
}

#[test]
fn raft_backed_store_applies_prepared_chunk_batches() {
    let raft = InMemoryRustRaft::new(1).unwrap();
    let store = MatrixObjectStore::new(test_options()).unwrap();
    let mut replicated = RaftBackedObjectStore::new(raft, store);
    let chunk_id = ChunkId {
        slab_id: SlabId {
            volume_id: 0,
            id: 991,
        },
        chunk_index: 0,
    };
    let writes = vec![(0, b"alpha".to_vec()), (5, b"-beta".to_vec())];
    let stale_chunk_control_checksum = replicated.store().page_service.replicas[0]
        .control_proof()
        .state_checksum;
    replicated
        .propose_configure_chunk_mutation_qos(ChunkMutationQosConfig {
            window_ms: 30_000,
            max_write_ops_per_window: 100,
            max_write_bytes_per_window: 1024 * 1024,
            max_discard_ops_per_window: 100,
            max_discard_bytes_per_window: 1024 * 1024,
        })
        .unwrap();
    let current_chunk_control_checksum = replicated.store().page_service.replicas[0]
        .control_proof()
        .state_checksum;
    assert_ne!(stale_chunk_control_checksum, current_chunk_control_checksum);
    assert!(matches!(
        replicated.prepare_chunk_batch_write_raft_entry_bounded_fenced(
            0,
            chunk_id.clone(),
            writes.clone(),
            1024,
            "prepared-chunk-write-stale-fence",
            Some(&stale_chunk_control_checksum),
        ),
        Err(ObjectError::PreconditionFailed(_))
    ));
    let proven_prepared_write = replicated
        .prepare_chunk_batch_write_raft_entry_bounded_with_read_proof_linearizable_fenced(
            0,
            chunk_id.clone(),
            writes.clone(),
            1024,
            "prepared-chunk-write-a",
            Some(&current_chunk_control_checksum),
        )
        .unwrap();
    assert_eq!(
        proven_prepared_write.proof.requested_storage_read_index,
        replicated.raft_commit_index()
    );
    assert_eq!(
        proven_prepared_write.proof.storage_applied_index,
        replicated.raft_commit_index()
    );
    assert_eq!(proven_prepared_write.proof.control_kind, "chunk-service");
    assert_eq!(
        proven_prepared_write.proof.control_checksum,
        current_chunk_control_checksum
    );
    let prepared_write = proven_prepared_write.value;
    assert_eq!(prepared_write.expected_previous_commit_index, 1);
    assert_eq!(prepared_write.prepared_commit_index, 2);
    assert_eq!(prepared_write.state.data, std::sync::Arc::new(b"alpha-beta".to_vec()));
    assert_eq!(
        prepared_write.control_proof.state_checksum,
        current_chunk_control_checksum
    );
    assert_eq!(
        prepared_write.expected_control_checksum,
        current_chunk_control_checksum
    );
    assert!(!prepared_write.raft_entry_checksum.is_empty());
    let bounded_prepared_write = replicated
        .prepare_chunk_batch_write_raft_entry_bounded_fenced(
            0,
            chunk_id.clone(),
            writes.clone(),
            5,
            "prepared-chunk-write-bounded-page",
            Some(&current_chunk_control_checksum),
        )
        .unwrap();
    assert_eq!(bounded_prepared_write.writes.len(), 1);
    assert_eq!(bounded_prepared_write.writes[0].0, 0);
    assert_eq!(bounded_prepared_write.writes[0].1, b"alpha".to_vec());
    assert_eq!(bounded_prepared_write.receipt.stats.input_bytes, 5);
    assert_eq!(bounded_prepared_write.receipt.stats.input_ranges, 1);
    assert_eq!(bounded_prepared_write.state.data, std::sync::Arc::new(b"alpha".to_vec()));
    let bounded_resume_prepared_write = replicated
        .prepare_chunk_batch_write_raft_entry_bounded_fenced_from(
            0,
            chunk_id.clone(),
            writes.clone(),
            5,
            1,
            "prepared-chunk-write-bounded-resume-page",
            Some(&current_chunk_control_checksum),
        )
        .unwrap();
    assert_eq!(bounded_resume_prepared_write.writes.len(), 1);
    assert_eq!(bounded_resume_prepared_write.writes[0].0, 5);
    assert_eq!(bounded_resume_prepared_write.writes[0].1, b"-beta".to_vec());
    assert_eq!(bounded_resume_prepared_write.receipt.stats.input_bytes, 5);
    assert_eq!(bounded_resume_prepared_write.receipt.stats.input_ranges, 1);
    assert_eq!(
        bounded_resume_prepared_write.state.data,
        std::sync::Arc::new(b"\0\0\0\0\0-beta".to_vec())
    );
    assert!(matches!(
        replicated.prepare_chunk_batch_write_raft_entry_bounded_fenced(
            0,
            chunk_id.clone(),
            vec![(0, b"oversize".to_vec())],
            4,
            "prepared-chunk-write-over-budget-first-range",
            Some(&current_chunk_control_checksum),
        ),
        Err(ObjectError::PreconditionFailed(_))
    ));
    let mut unfenced_prepared_write = prepared_write.clone();
    unfenced_prepared_write.expected_control_checksum.clear();
    unfenced_prepared_write.raft_entry_checksum =
        prepared_chunk_batch_write_checksum(&unfenced_prepared_write);
    let unfenced_prepared_write_checksum = unfenced_prepared_write.raft_entry_checksum.clone();
    assert!(matches!(
        replicated
            .store()
            .clone()
            .apply_prepared_chunk_batch_write(unfenced_prepared_write.clone()),
        Err(ObjectError::PreconditionFailed(_))
    ));
    assert!(matches!(
        replicated.propose_prepared_chunk_batch_write_linearizable_fenced(
            unfenced_prepared_write.clone(),
            Some(&current_chunk_control_checksum),
            &unfenced_prepared_write_checksum,
        ),
        Err(ObjectError::PreconditionFailed(_))
    ));
    assert!(matches!(
        replicated.propose_prepared_chunk_batch_write_linearizable_fenced(
            prepared_write.clone(),
            None,
            &prepared_write.raft_entry_checksum,
        ),
        Err(ObjectError::PreconditionFailed(_))
    ));
    assert!(matches!(
        replicated.propose_prepared_chunk_batch_write_linearizable_fenced(
            prepared_write.clone(),
            Some(""),
            &prepared_write.raft_entry_checksum,
        ),
        Err(ObjectError::PreconditionFailed(_))
    ));
    assert!(replicated
        .store()
        .page_service
        .replicas
        .get(0)
        .unwrap()
        .read_chunk(&chunk_id, 0, 1)
        .is_err());

    let mut tampered = prepared_write.clone();
    std::sync::Arc::make_mut(&mut tampered.state.data)[0] = b'X';
    assert!(matches!(
        replicated
            .store()
            .clone()
            .apply_command(ObjectCommand::ApplyPreparedChunkBatchWrite { prepared: tampered }),
        Err(ObjectError::Corruption(_))
    ));

    assert!(matches!(
        replicated.propose_prepared_chunk_batch_write_linearizable_fenced(
            prepared_write.clone(),
            Some(&stale_chunk_control_checksum),
            &prepared_write.raft_entry_checksum,
        ),
        Err(ObjectError::PreconditionFailed(_))
    ));
    assert!(matches!(
        replicated.propose_prepared_chunk_batch_write_linearizable_fenced(
            prepared_write.clone(),
            Some(&current_chunk_control_checksum),
            "",
        ),
        Err(ObjectError::PreconditionFailed(_))
    ));
    assert!(matches!(
        replicated.propose_prepared_chunk_batch_write_linearizable_fenced(
            prepared_write.clone(),
            Some(&current_chunk_control_checksum),
            "etag:stale",
        ),
        Err(ObjectError::PreconditionFailed(_))
    ));
    let mut stale_cursor_prepared_write = prepared_write.clone();
    stale_cursor_prepared_write
        .control_proof
        .chunk_mutation_control_next_log_index = stale_cursor_prepared_write
        .control_proof
        .chunk_mutation_control_next_log_index
        .saturating_add(1);
    stale_cursor_prepared_write.raft_entry_checksum =
        prepared_chunk_batch_write_checksum(&stale_cursor_prepared_write);
    let stale_cursor_prepared_write_checksum =
        stale_cursor_prepared_write.raft_entry_checksum.clone();
    assert!(matches!(
        replicated
            .store()
            .clone()
            .apply_prepared_chunk_batch_write(stale_cursor_prepared_write.clone()),
        Err(ObjectError::PreconditionFailed(_))
    ));
    assert!(matches!(
        replicated.propose_prepared_chunk_batch_write_linearizable_fenced(
            stale_cursor_prepared_write,
            Some(&current_chunk_control_checksum),
            &stale_cursor_prepared_write_checksum,
        ),
        Err(ObjectError::PreconditionFailed(_))
    ));
    let applied_write = replicated
        .propose_prepared_chunk_batch_write_linearizable_fenced(
            prepared_write.clone(),
            Some(&current_chunk_control_checksum),
            &prepared_write.raft_entry_checksum,
        )
        .unwrap();
    assert_eq!(
        applied_write.content_type,
        "chunkserver/prepared-batch-write"
    );
    assert_eq!(replicated.raft_commit_index(), 2);

    let post_write_chunk_control_checksum = replicated.store().page_service.replicas[0]
        .control_proof()
        .state_checksum;
    assert!(matches!(
        replicated.prepare_chunk_batch_discard_raft_entry_bounded_fenced(
            0,
            chunk_id.clone(),
            vec![DataRange {
                offset: 2,
                length: 4,
            }],
            1024,
            "prepared-chunk-discard-stale-fence",
            Some(&stale_chunk_control_checksum),
        ),
        Err(ObjectError::PreconditionFailed(_))
    ));
    let proven_prepared_discard = replicated
        .prepare_chunk_batch_discard_raft_entry_bounded_with_read_proof_linearizable_fenced(
            0,
            chunk_id.clone(),
            vec![DataRange {
                offset: 2,
                length: 4,
            }],
            1024,
            "prepared-chunk-discard-a",
            Some(&post_write_chunk_control_checksum),
        )
        .unwrap();
    assert_eq!(
        proven_prepared_discard.proof.requested_storage_read_index,
        replicated.raft_commit_index()
    );
    assert_eq!(
        proven_prepared_discard.proof.storage_applied_index,
        replicated.raft_commit_index()
    );
    assert_eq!(proven_prepared_discard.proof.control_kind, "chunk-service");
    assert_eq!(
        proven_prepared_discard.proof.control_checksum,
        post_write_chunk_control_checksum
    );
    let prepared_discard = proven_prepared_discard.value;
    assert_eq!(prepared_discard.expected_previous_commit_index, 2);
    assert_eq!(prepared_discard.prepared_commit_index, 3);
    assert_eq!(prepared_discard.state.discarded_ranges.len(), 1);
    assert_eq!(
        prepared_discard.control_proof.state_checksum,
        post_write_chunk_control_checksum
    );
    assert_eq!(
        prepared_discard.expected_control_checksum,
        post_write_chunk_control_checksum
    );
    let bounded_prepared_discard = replicated
        .prepare_chunk_batch_discard_raft_entry_bounded_fenced(
            0,
            chunk_id.clone(),
            vec![
                DataRange {
                    offset: 0,
                    length: 2,
                },
                DataRange {
                    offset: 6,
                    length: 2,
                },
            ],
            2,
            "prepared-chunk-discard-bounded-page",
            Some(&post_write_chunk_control_checksum),
        )
        .unwrap();
    assert_eq!(bounded_prepared_discard.ranges.len(), 1);
    assert_eq!(bounded_prepared_discard.ranges[0].offset, 0);
    assert_eq!(bounded_prepared_discard.ranges[0].length, 2);
    assert_eq!(bounded_prepared_discard.receipt.stats.input_bytes, 2);
    assert_eq!(bounded_prepared_discard.receipt.stats.input_ranges, 1);
    let bounded_resume_prepared_discard = replicated
        .prepare_chunk_batch_discard_raft_entry_bounded_fenced_from(
            0,
            chunk_id.clone(),
            vec![
                DataRange {
                    offset: 0,
                    length: 2,
                },
                DataRange {
                    offset: 6,
                    length: 2,
                },
            ],
            2,
            1,
            "prepared-chunk-discard-bounded-resume-page",
            Some(&post_write_chunk_control_checksum),
        )
        .unwrap();
    assert_eq!(bounded_resume_prepared_discard.ranges.len(), 1);
    assert_eq!(bounded_resume_prepared_discard.ranges[0].offset, 6);
    assert_eq!(bounded_resume_prepared_discard.ranges[0].length, 2);
    assert_eq!(bounded_resume_prepared_discard.receipt.stats.input_bytes, 2);
    assert_eq!(
        bounded_resume_prepared_discard.receipt.stats.input_ranges,
        1
    );
    assert!(matches!(
        replicated.prepare_chunk_batch_discard_raft_entry_bounded_fenced(
            0,
            chunk_id.clone(),
            vec![DataRange {
                offset: 0,
                length: 3,
            }],
            2,
            "prepared-chunk-discard-over-budget-first-range",
            Some(&post_write_chunk_control_checksum),
        ),
        Err(ObjectError::PreconditionFailed(_))
    ));
    let mut unfenced_prepared_discard = prepared_discard.clone();
    unfenced_prepared_discard.expected_control_checksum.clear();
    unfenced_prepared_discard.raft_entry_checksum =
        prepared_chunk_batch_discard_checksum(&unfenced_prepared_discard);
    let unfenced_prepared_discard_checksum = unfenced_prepared_discard.raft_entry_checksum.clone();
    assert!(matches!(
        replicated
            .store()
            .clone()
            .apply_prepared_chunk_batch_discard(unfenced_prepared_discard.clone()),
        Err(ObjectError::PreconditionFailed(_))
    ));
    assert!(matches!(
        replicated.propose_prepared_chunk_batch_discard_linearizable_fenced(
            unfenced_prepared_discard.clone(),
            Some(&post_write_chunk_control_checksum),
            &unfenced_prepared_discard_checksum,
        ),
        Err(ObjectError::PreconditionFailed(_))
    ));
    assert!(matches!(
        replicated.propose_prepared_chunk_batch_discard_linearizable_fenced(
            prepared_discard.clone(),
            None,
            &prepared_discard.raft_entry_checksum,
        ),
        Err(ObjectError::PreconditionFailed(_))
    ));
    assert!(matches!(
        replicated.propose_prepared_chunk_batch_discard_linearizable_fenced(
            prepared_discard.clone(),
            Some(""),
            &prepared_discard.raft_entry_checksum,
        ),
        Err(ObjectError::PreconditionFailed(_))
    ));
    assert!(matches!(
        replicated.propose_prepared_chunk_batch_discard_linearizable_fenced(
            prepared_discard.clone(),
            Some(&current_chunk_control_checksum),
            &prepared_discard.raft_entry_checksum,
        ),
        Err(ObjectError::PreconditionFailed(_))
    ));
    assert!(matches!(
        replicated.propose_prepared_chunk_batch_discard_linearizable_fenced(
            prepared_discard.clone(),
            Some(&post_write_chunk_control_checksum),
            "",
        ),
        Err(ObjectError::PreconditionFailed(_))
    ));
    assert!(matches!(
        replicated.propose_prepared_chunk_batch_discard_linearizable_fenced(
            prepared_discard.clone(),
            Some(&post_write_chunk_control_checksum),
            "etag:stale",
        ),
        Err(ObjectError::PreconditionFailed(_))
    ));
    let mut stale_cursor_prepared_discard = prepared_discard.clone();
    stale_cursor_prepared_discard
        .control_proof
        .chunk_mutation_control_commit_index = stale_cursor_prepared_discard
        .control_proof
        .chunk_mutation_control_commit_index
        .saturating_add(1);
    stale_cursor_prepared_discard.raft_entry_checksum =
        prepared_chunk_batch_discard_checksum(&stale_cursor_prepared_discard);
    let stale_cursor_prepared_discard_checksum =
        stale_cursor_prepared_discard.raft_entry_checksum.clone();
    assert!(matches!(
        replicated
            .store()
            .clone()
            .apply_prepared_chunk_batch_discard(stale_cursor_prepared_discard.clone()),
        Err(ObjectError::PreconditionFailed(_))
    ));
    assert!(matches!(
        replicated.propose_prepared_chunk_batch_discard_linearizable_fenced(
            stale_cursor_prepared_discard,
            Some(&post_write_chunk_control_checksum),
            &stale_cursor_prepared_discard_checksum,
        ),
        Err(ObjectError::PreconditionFailed(_))
    ));
    prepared_discard
        .verify_expected_raft_entry_checksum(&prepared_discard.raft_entry_checksum)
        .unwrap();
    replicated
        .store()
        .page_service
        .replicas
        .get(0)
        .unwrap()
        .check_expected_control_checksum(Some(&post_write_chunk_control_checksum))
        .unwrap();
    let applied_discard = replicated
        .propose_prepared_chunk_batch_discard_with_status(prepared_discard.clone())
        .unwrap();
    assert_eq!(applied_discard.mutation_id, "prepared-chunk-discard-a");
    assert_eq!(applied_discard.mutation_commit_index, 3);
    assert_eq!(applied_discard.next_log_index, 4);
    assert!(applied_discard.committed);
    assert!(!applied_discard.prepared);
    assert!(!applied_discard.external_raft_required);
    assert!(!applied_discard.deduped);
    assert_eq!(
        applied_discard.metadata.content_type,
        "chunkserver/prepared-batch-discard"
    );
    assert_eq!(
        applied_discard
            .to_control_fields("chunk_discard.")
            .get("chunk_discard.mutation_id"),
        Some(&"prepared-chunk-discard-a".to_string())
    );
    assert_eq!(replicated.raft_commit_index(), 3);

    let mut follower = MatrixObjectStore::new(test_options()).unwrap();
    replicated.replay_into(&mut follower).unwrap();
    assert_eq!(follower.last_applied_index(), 3);
    let follower_replica = follower.page_service.replicas.get(0).unwrap();
    assert_eq!(
        follower_replica.read_chunk(&chunk_id, 0, 2).unwrap().data,
        b"al".to_vec()
    );
    assert!(matches!(
        follower_replica.read_chunk(&chunk_id, 0, 10),
        Err(ObjectError::Corruption(_))
    ));
    assert_eq!(
        follower_replica
            .read_chunk_state(&chunk_id)
            .unwrap()
            .discarded_ranges,
        vec![DataRange {
            offset: 2,
            length: 4
        }]
    );
    assert_eq!(
        follower_replica
            .list_batch_write_receipts(None, 10, Some(&chunk_id))
            .unwrap()
            .receipt_count,
        1
    );
    assert_eq!(
        follower_replica
            .list_batch_discard_receipts(None, 10, Some(&chunk_id))
            .unwrap()
            .receipt_count,
        1
    );

    let dedupe_prepared = replicated
        .prepare_chunk_batch_write_raft_entry(0, chunk_id, writes, "prepared-chunk-write-a")
        .unwrap();
    let deduped = replicated
        .propose_prepared_chunk_batch_write_with_status(dedupe_prepared)
        .unwrap();
    assert_eq!(deduped.mutation_id, "prepared-chunk-write-a");
    assert_eq!(deduped.mutation_commit_index, 4);
    assert_eq!(deduped.next_log_index, 5);
    assert!(deduped.committed);
    assert!(!deduped.prepared);
    assert!(!deduped.external_raft_required);
    assert!(deduped.deduped);
    assert_eq!(
        deduped.metadata.content_type,
        "chunkserver/prepared-batch-write-deduped"
    );
    assert_eq!(
        deduped
            .to_control_fields("chunk_write.")
            .get("chunk_write.mutation_id"),
        Some(&"prepared-chunk-write-a".to_string())
    );
    assert_eq!(replicated.raft_commit_index(), 4);
}

#[test]
fn raft_backed_store_replays_metaserver_snapshot_compaction_floor() {
    let raft = InMemoryRustRaft::new(1).unwrap();
    let store = MatrixObjectStore::new(test_options()).unwrap();
    let mut replicated = RaftBackedObjectStore::new(raft, store);
    let first_mutations = vec![MetadataMutation {
        key: "object/snapshot-floor/a".to_string().into(),
        value: "etag=a length=1".to_string(),
        expected_version: 0,
        delete: false,
    }];
    replicated
        .propose_commit_metadata_batch_idempotent(
            first_mutations,
            None,
            None,
            10,
            "snapshot-floor-batch-a",
        )
        .unwrap();
    replicated
        .propose_commit_metadata_batch_idempotent(
            vec![MetadataMutation {
                key: "object/snapshot-floor/b".to_string().into(),
                value: "etag=b length=2".to_string(),
                expected_version: 0,
                delete: false,
            }],
            None,
            None,
            11,
            "snapshot-floor-batch-b",
        )
        .unwrap();
    assert_eq!(
        replicated
            .store()
            .export_snapshot().unwrap()
            .meta_snapshot
            .batch_request_receipts
            .len(),
        2
    );
    replicated
        .propose_acquire_metadata_lease_idempotent(
            "object/snapshot-floor/",
            "writer-a",
            100,
            20,
            "snapshot-floor-lease-acquire",
        )
        .unwrap();
    replicated
        .propose_release_metadata_lease_idempotent(
            "object/snapshot-floor/",
            "writer-a",
            1,
            "snapshot-floor-lease-release",
        )
        .unwrap();
    replicated
        .propose_register_meta_coordinator_session_idempotent(
            "snapshot-floor-session",
            "meta-a",
            "127.0.0.1:9100",
            100,
            30,
            "snapshot-floor-session-register",
        )
        .unwrap();
    replicated
        .propose_release_meta_coordinator_session_idempotent(
            "snapshot-floor-session",
            "meta-a",
            1,
            "snapshot-floor-session-release",
        )
        .unwrap();
    let pre_compact_snapshot = replicated.store().export_snapshot().unwrap().meta_snapshot;
    assert_eq!(pre_compact_snapshot.lease_receipts.len(), 2);
    assert_eq!(pre_compact_snapshot.coordinator_session_receipts.len(), 2);

    let compacted = replicated.propose_compact_meta_snapshot(6, 0, 0).unwrap();
    assert_eq!(compacted.content_type, "metaserver/snapshot-compact");
    assert_eq!(compacted.version, 6);
    assert_eq!(compacted.length, 8);
    assert_eq!(replicated.raft_commit_index(), 7);

    let mut follower = MatrixObjectStore::new(test_options()).unwrap();
    replicated.replay_into(&mut follower).unwrap();
    assert_eq!(follower.last_applied_index(), 7);
    assert!(follower.metadata_changes_after(0, 10).is_empty());
    let snapshot = follower.export_snapshot().unwrap();
    assert_eq!(snapshot.meta_snapshot.raft_snapshot_floor_commit_index, 6);
    assert_eq!(
        snapshot.meta_snapshot.raft_snapshot_compacted_change_count,
        2
    );
    assert_eq!(
        snapshot
            .meta_snapshot
            .raft_snapshot_compacted_batch_receipt_count,
        6
    );
    let metadata_ready = follower.metadata_raft_readiness(0, 100);
    assert_eq!(metadata_ready.raft_snapshot_floor_commit_index, 6);
    assert_eq!(metadata_ready.raft_snapshot_compacted_change_count, 2);
    assert_eq!(
        metadata_ready.raft_snapshot_compacted_batch_receipt_count,
        6
    );
    assert_eq!(metadata_ready.retained_change_records, 0);
    assert_eq!(metadata_ready.first_retained_change_sequence, 0);
    assert_eq!(metadata_ready.last_retained_change_sequence, 0);
    assert_eq!(metadata_ready.max_retained_metadata_commit_index, 6);
    assert!(snapshot.meta_snapshot.batch_request_receipts.is_empty());
    assert!(snapshot.meta_snapshot.lease_receipts.is_empty());
    assert!(snapshot
        .meta_snapshot
        .coordinator_session_receipts
        .is_empty());

    let restored_snapshot =
        MetaSnapshot::from_bytes(&snapshot.meta_snapshot.to_bytes().unwrap()).unwrap();
    assert_eq!(restored_snapshot.raft_snapshot_floor_commit_index, 6);
    assert_eq!(restored_snapshot.raft_snapshot_compacted_change_count, 2);
    assert_eq!(
        restored_snapshot.raft_snapshot_compacted_batch_receipt_count,
        6
    );
    assert!(restored_snapshot.lease_receipts.is_empty());
    assert!(restored_snapshot.coordinator_session_receipts.is_empty());

    let mut restored = MatrixObjectStore::new(test_options()).unwrap();
    restored.install_snapshot(snapshot).unwrap();
    assert!(restored.metadata_changes_after(0, 10).is_empty());
    assert_eq!(
        restored
            .export_snapshot().unwrap()
            .meta_snapshot
            .raft_snapshot_floor_commit_index,
        6
    );
}

#[test]
fn raft_backed_store_applies_prepared_metaserver_snapshot_compaction() {
    let raft = InMemoryRustRaft::new(1).unwrap();
    let store = MatrixObjectStore::new(test_options()).unwrap();
    let mut replicated = RaftBackedObjectStore::new(raft, store);
    replicated
        .propose_commit_metadata_batch_idempotent(
            vec![MetadataMutation {
                key: "object/prepared-snapshot/a".to_string().into(),
                value: "etag=a length=1".to_string(),
                expected_version: 0,
                delete: false,
            }],
            None,
            None,
            10,
            "prepared-snapshot-batch-a",
        )
        .unwrap();
    replicated
        .propose_commit_metadata_batch_idempotent(
            vec![MetadataMutation {
                key: "object/prepared-snapshot/b".to_string().into(),
                value: "etag=b length=2".to_string(),
                expected_version: 0,
                delete: false,
            }],
            None,
            None,
            11,
            "prepared-snapshot-batch-b",
        )
        .unwrap();
    replicated
        .propose_acquire_metadata_lease_idempotent(
            "object/prepared-snapshot/",
            "writer-a",
            100,
            20,
            "prepared-snapshot-lease-acquire",
        )
        .unwrap();
    replicated
        .propose_release_metadata_lease_idempotent(
            "object/prepared-snapshot/",
            "writer-a",
            1,
            "prepared-snapshot-lease-release",
        )
        .unwrap();
    replicated
        .propose_register_meta_coordinator_session_idempotent(
            "prepared-snapshot-session",
            "meta-a",
            "127.0.0.1:9100",
            100,
            30,
            "prepared-snapshot-session-register",
        )
        .unwrap();
    replicated
        .propose_release_meta_coordinator_session_idempotent(
            "prepared-snapshot-session",
            "meta-a",
            1,
            "prepared-snapshot-session-release",
        )
        .unwrap();

    let proven_prepared = replicated
        .prepare_compact_meta_snapshot_raft_entry_with_read_proof_linearizable(6, 0, 0, 40)
        .unwrap();
    assert_eq!(proven_prepared.proof.requested_read_index, 6);
    assert_eq!(proven_prepared.proof.metadata_commit_index, 6);
    let prepared = proven_prepared.value;
    assert_eq!(prepared.expected_previous_commit_index, 6);
    assert_eq!(prepared.prepared_commit_index, 7);
    assert_eq!(prepared.report.raft_snapshot_floor_commit_index, 6);
    assert_eq!(prepared.report.compacted_change_records, 2);
    assert_eq!(prepared.report.compacted_batch_receipts, 2);
    assert_eq!(prepared.report.compacted_lease_receipts, 2);
    assert_eq!(prepared.report.compacted_coordinator_session_receipts, 2);
    assert_eq!(prepared.snapshot.raft_snapshot_floor_commit_index, 6);
    assert!(prepared
        .mutation_id
        .starts_with("meta-snapshot-compaction-6-7-"));
    assert!(!prepared.before_state_fingerprint.is_empty());
    assert!(!prepared.request_checksum.is_empty());
    assert!(!prepared.raft_entry_checksum.is_empty());

    let mut tampered = prepared.clone();
    tampered.snapshot.raft_snapshot_floor_commit_index = 5;
    assert!(matches!(
        replicated.store().clone().apply_command(
            ObjectCommand::ApplyPreparedMetaSnapshotCompaction { prepared: tampered }
        ),
        Err(ObjectError::Corruption(_))
    ));

    let compacted = replicated
        .propose_prepared_meta_snapshot_compaction(prepared.clone())
        .unwrap();
    assert_eq!(
        compacted.content_type,
        "metaserver/prepared-snapshot-compact"
    );
    assert_eq!(compacted.version, 6);
    assert_eq!(compacted.length, 8);
    assert_eq!(replicated.raft_commit_index(), 7);

    let apply_report = replicated
        .propose_prepared_meta_snapshot_compaction_with_status(prepared.clone())
        .unwrap();
    assert_eq!(apply_report.mutation_id, prepared.mutation_id);
    assert_eq!(
        apply_report.mutation_request_checksum,
        prepared.request_checksum
    );
    assert_eq!(apply_report.mutation_commit_index, 8);
    assert_eq!(apply_report.next_log_index, 9);
    assert!(apply_report.committed);
    assert!(!apply_report.prepared);
    assert!(!apply_report.external_raft_required);
    assert!(apply_report.deduped);
    assert_eq!(
        apply_report
            .to_control_fields("snapshot.")
            .get("snapshot.mutation_id"),
        Some(&prepared.mutation_id)
    );

    let mut follower = MatrixObjectStore::new(test_options()).unwrap();
    replicated.replay_into(&mut follower).unwrap();
    assert_eq!(follower.last_applied_index(), 8);
    let snapshot = follower.export_snapshot().unwrap();
    assert_eq!(snapshot.meta_snapshot.raft_snapshot_floor_commit_index, 6);
    assert_eq!(
        snapshot.meta_snapshot.raft_snapshot_compacted_change_count,
        2
    );
    assert_eq!(
        snapshot
            .meta_snapshot
            .raft_snapshot_compacted_batch_receipt_count,
        6
    );
    assert!(snapshot.meta_snapshot.batch_request_receipts.is_empty());
    assert!(snapshot.meta_snapshot.lease_receipts.is_empty());
    assert!(snapshot
        .meta_snapshot
        .coordinator_session_receipts
        .is_empty());
}

#[test]
fn raft_backed_store_applies_prepared_metaserver_shard_record_handoff() {
    let raft = InMemoryRustRaft::new(1).unwrap();
    let store = MatrixObjectStore::new(test_options()).unwrap();
    let mut replicated = RaftBackedObjectStore::new(raft, store);
    replicated
        .propose_configure_meta_shard(MetadataShard {
            shard_id: "objects-handoff".to_string(),
            start_key: "object/handoff/".to_string(),
            end_key: "object/handoff0".to_string(),
            owner_node_id: "meta-a".to_string(),
            epoch: 1,
            draining: false,
        })
        .unwrap();
    replicated
        .propose_commit_metadata_batch_idempotent(
            vec![
                MetadataMutation {
                    key: "object/handoff/a".to_string().into(),
                    value: "etag=a length=1".to_string(),
                    expected_version: 0,
                    delete: false,
                },
                MetadataMutation {
                    key: "object/handoff/b".to_string().into(),
                    value: "etag=b length=2".to_string(),
                    expected_version: 0,
                    delete: false,
                },
            ],
            None,
            None,
            20,
            "handoff-source-batch",
        )
        .unwrap();

    let lagging_source = RaftBackedObjectStore::new(
        InMemoryRustRaft {
            term: 1,
            commit_index: replicated.raft_commit_index().saturating_add(1),
            entries: Vec::new(),
        },
        replicated.store().clone(),
    );
    assert!(matches!(
        lagging_source.prepare_meta_shard_record_handoff_raft_entry_linearizable(
            "objects-handoff",
            None,
            16,
            4096,
            false,
            "meta-a",
            Some("meta-a"),
            Some(1),
            Some("handoff-token-stale"),
            "apply-handoff-stale",
            25,
        ),
        Err(ObjectError::PreconditionFailed(_))
    ));

    assert!(matches!(
        replicated.prepare_meta_shard_record_handoff_raft_entry_linearizable(
            "objects-handoff",
            None,
            16,
            4096,
            false,
            "meta-a",
            Some("meta-b"),
            Some(1),
            Some("handoff-token-wrong-owner"),
            "apply-handoff-wrong-owner",
            25,
        ),
        Err(ObjectError::PreconditionFailed(_))
    ));
    assert!(matches!(
        replicated.prepare_meta_shard_record_handoff_raft_entry_linearizable(
            "objects-handoff",
            None,
            16,
            4096,
            false,
            "meta-a",
            Some("meta-a"),
            Some(2),
            Some("handoff-token-wrong-epoch"),
            "apply-handoff-wrong-epoch",
            25,
        ),
        Err(ObjectError::PreconditionFailed(_))
    ));

    let (prepared, readiness) = replicated
        .prepare_meta_shard_record_handoff_raft_entry_linearizable(
            "objects-handoff",
            None,
            16,
            4096,
            false,
            "meta-a",
            Some("meta-a"),
            Some(1),
            Some("handoff-token-a"),
            "apply-handoff-a",
            25,
        )
        .unwrap();
    assert!(readiness.readable);
    assert!(readiness.raft_log_commit_index >= replicated.raft_commit_index());
    assert_eq!(prepared.expected_previous_commit_index, 3);
    assert_eq!(prepared.prepared_commit_index, 4);
    assert_eq!(prepared.records.len(), 2);
    assert_eq!(prepared.source_commit_index, 3);
    assert_eq!(prepared.source_read_index, 3);
    assert_eq!(prepared.source_shard_topology_epoch, 1);
    assert_eq!(prepared.handoff_token, "handoff-token-a");
    assert!(!prepared.handoff_batch_checksum.is_empty());
    assert!(!prepared.raft_entry_checksum.is_empty());

    let mut tampered = prepared.clone();
    tampered.records[0].value = "tampered".to_string().into();
    assert!(matches!(
        replicated.store().clone().apply_command(
            ObjectCommand::ApplyPreparedMetaShardRecordHandoff { prepared: tampered }
        ),
        Err(ObjectError::Corruption(_))
    ));

    let apply_report = replicated
        .propose_prepared_meta_shard_record_handoff_with_status(prepared.clone())
        .unwrap();
    let applied = apply_report.metadata.clone();
    assert_eq!(
        applied.content_type,
        "metaserver/prepared-shard-record-handoff"
    );
    assert_eq!(applied.version, 2);
    assert_eq!(applied.length, 4);
    assert_eq!(replicated.raft_commit_index(), 3);
    assert_eq!(apply_report.mutation_id, "apply-handoff-a");
    assert_eq!(
        apply_report.mutation_request_checksum,
        metadata_shard_record_handoff_request_checksum(&prepared)
    );
    assert_eq!(
        apply_report.mutation_commit_index,
        replicated.raft_commit_index()
    );
    assert_eq!(
        apply_report.next_log_index,
        apply_report.mutation_commit_index.saturating_add(1)
    );
    assert!(apply_report.committed);
    assert!(!apply_report.prepared);
    assert!(!apply_report.external_raft_required);
    assert!(!apply_report.deduped);
    assert_eq!(apply_report.source_node_id, "meta-a");
    assert_eq!(apply_report.handoff_token, "handoff-token-a");
    assert_eq!(
        apply_report.handoff_batch_checksum,
        prepared.handoff_batch_checksum
    );
    assert_eq!(
        apply_report.raft_entry_checksum,
        prepared.raft_entry_checksum
    );
    assert_eq!(apply_report.source_commit_index, 3);
    assert_eq!(apply_report.source_read_index, 3);
    assert_eq!(apply_report.source_shard_topology_epoch, 1);
    assert_eq!(apply_report.record_count, 2);
    assert_eq!(apply_report.scanned_records, prepared.scanned_records);
    assert_eq!(apply_report.payload_bytes, prepared.payload_bytes);
    assert_eq!(apply_report.shard.shard_id, "objects-handoff");
    assert_eq!(apply_report.receipt.first_commit_index, 4);
    assert_eq!(apply_report.receipt.records.len(), 2);
    let apply_fields = apply_report.to_control_fields("handoff.");
    assert_eq!(
        apply_fields.get("handoff.record_count"),
        Some(&"2".to_string())
    );
    assert_eq!(
        apply_fields.get("handoff.receipt_proof_checksum"),
        Some(&apply_report.receipt.proof_checksum())
    );
    assert_eq!(
        apply_fields.get("handoff.metadata.content_type"),
        Some(&"metaserver/prepared-shard-record-handoff".to_string())
    );

    let mut follower = MatrixObjectStore::new(test_options()).unwrap();
    replicated.replay_into(&mut follower).unwrap();
    assert_eq!(follower.last_applied_index(), 3);
    assert_eq!(
        follower.metadata_record("object/handoff/a").unwrap().value,
        "etag=a length=1".into()
    );
    let snapshot = follower.export_snapshot().unwrap();
    let receipt = snapshot
        .meta_snapshot
        .batch_request_receipts
        .get("apply-handoff-a")
        .unwrap();
    assert_eq!(receipt.first_commit_index, 4);
    assert_eq!(receipt.records.len(), 2);
    assert_eq!(receipt.expected_owner, "meta-a");
    assert_eq!(receipt.expected_epoch, 1);
}

#[test]
fn raft_backed_store_applies_prepared_metaserver_retention_config() {
    let raft = InMemoryRustRaft::new(1).unwrap();
    let store = MatrixObjectStore::new(test_options()).unwrap();
    let mut replicated = RaftBackedObjectStore::new(raft, store);
    replicated
        .propose_commit_metadata_batch_idempotent(
            vec![MetadataMutation {
                key: "object/prepared-retention/a".to_string().into(),
                value: "etag=a length=1".to_string(),
                expected_version: 0,
                delete: false,
            }],
            None,
            None,
            10,
            "prepared-retention-batch-a",
        )
        .unwrap();
    replicated
        .propose_commit_metadata_batch_idempotent(
            vec![MetadataMutation {
                key: "object/prepared-retention/b".to_string().into(),
                value: "etag=b length=2".to_string(),
                expected_version: 0,
                delete: false,
            }],
            None,
            None,
            11,
            "prepared-retention-batch-b",
        )
        .unwrap();
    assert_eq!(replicated.store().metadata_changes_after(0, 10).len(), 2);
    assert_eq!(
        replicated
            .store()
            .export_snapshot().unwrap()
            .meta_snapshot
            .batch_request_receipts
            .len(),
        2
    );

    let prepared = replicated
        .prepare_configure_meta_retention_raft_entry(1, 1)
        .unwrap();
    assert_eq!(prepared.expected_previous_commit_index, 2);
    assert_eq!(prepared.prepared_commit_index, 3);
    assert_eq!(prepared.report.trimmed_change_records, 1);
    assert_eq!(prepared.report.trimmed_batch_receipts, 1);
    assert_eq!(prepared.report.retained_change_records, 1);
    assert_eq!(prepared.report.retained_mutation_receipts, 1);
    assert!(!prepared.before_state_fingerprint.is_empty());
    assert!(!prepared.request_checksum.is_empty());
    assert!(!prepared.raft_entry_checksum.is_empty());

    let mut tampered = prepared.clone();
    tampered.change_log_retention_limit = 2;
    assert!(matches!(
        replicated
            .store()
            .clone()
            .apply_command(ObjectCommand::ApplyPreparedMetaRetentionConfig { prepared: tampered }),
        Err(ObjectError::Corruption(_))
    ));

    let applied = replicated
        .propose_prepared_meta_retention_config(prepared.clone())
        .unwrap();
    assert_eq!(applied.content_type, "metaserver/prepared-retention-config");
    assert_eq!(applied.version, 1);
    assert_eq!(applied.length, 1);
    assert_eq!(applied.update_time_ms, 2);
    assert_eq!(replicated.raft_commit_index(), 3);

    let mut follower = MatrixObjectStore::new(test_options()).unwrap();
    replicated.replay_into(&mut follower).unwrap();
    assert_eq!(follower.last_applied_index(), 3);
    let readiness = follower.metadata_raft_readiness(0, 100);
    assert_eq!(readiness.change_log_retention_limit, 1);
    assert_eq!(readiness.mutation_receipt_retention_limit, 1);
    assert_eq!(readiness.retained_change_records, 1);
    let snapshot = follower.export_snapshot().unwrap();
    assert_eq!(snapshot.meta_snapshot.change_log_retention_limit, 1);
    assert_eq!(snapshot.meta_snapshot.mutation_receipt_retention_limit, 1);
    assert_eq!(snapshot.meta_snapshot.changes.len(), 1);
    assert_eq!(snapshot.meta_snapshot.batch_request_receipts.len(), 1);
    let restored = MetaSnapshot::from_bytes(&snapshot.meta_snapshot.to_bytes().unwrap()).unwrap();
    assert_eq!(restored.change_log_retention_limit, 1);
    assert_eq!(restored.mutation_receipt_retention_limit, 1);
}

#[test]
fn raft_backed_store_applies_prepared_metaserver_admission_policy() {
    let raft = InMemoryRustRaft::new(1).unwrap();
    let store = MatrixObjectStore::new(test_options()).unwrap();
    let mut replicated = RaftBackedObjectStore::new(raft, store);
    replicated
        .propose_commit_metadata_batch_idempotent(
            vec![MetadataMutation {
                key: "object/prepared-admission/a".to_string().into(),
                value: "etag=a length=1".to_string(),
                expected_version: 0,
                delete: false,
            }],
            None,
            None,
            10,
            "prepared-admission-batch-a",
        )
        .unwrap();

    let policy = MetadataAdmissionPolicy {
        max_batch_mutations: 7,
        max_batch_value_bytes: 4096,
        max_open_transactions: 3,
        max_namespace_leases: 5,
        max_coordinator_sessions: 2,
        max_shards: 11,
    };
    let prepared = replicated
        .prepare_configure_meta_admission_policy_raft_entry(policy.clone())
        .unwrap();
    assert_eq!(prepared.expected_previous_commit_index, 1);
    assert_eq!(prepared.prepared_commit_index, 2);
    assert_eq!(prepared.policy, policy);
    assert!(!prepared.before_state_fingerprint.is_empty());
    assert!(!prepared.request_checksum.is_empty());
    assert!(!prepared.raft_entry_checksum.is_empty());

    let mut tampered = prepared.clone();
    tampered.policy.max_open_transactions = 4;
    assert!(matches!(
        replicated
            .store()
            .clone()
            .apply_command(ObjectCommand::ApplyPreparedMetaAdmissionPolicy { prepared: tampered }),
        Err(ObjectError::Corruption(_))
    ));

    let applied = replicated
        .propose_prepared_meta_admission_policy(prepared)
        .unwrap();
    assert_eq!(applied.content_type, "metaserver/prepared-admission-policy");
    assert_eq!(applied.version, 7);
    assert_eq!(applied.length, 4096);
    assert_eq!(applied.update_time_ms, 3);
    assert_eq!(replicated.raft_commit_index(), 2);

    let mut follower = MatrixObjectStore::new(test_options()).unwrap();
    replicated.replay_into(&mut follower).unwrap();
    assert_eq!(follower.last_applied_index(), 2);
    assert_eq!(follower.metadata_admission_policy(), policy);
    let readiness = follower.metadata_raft_readiness(0, 100);
    assert_eq!(readiness.max_batch_mutations, 7);
    assert_eq!(readiness.max_batch_value_bytes, 4096);
    assert_eq!(readiness.max_open_transactions, 3);
}

#[test]
fn raft_backed_store_replays_idempotent_owner_fenced_metaserver_writes() {
    let raft = InMemoryRustRaft::new(1).unwrap();
    let store = MatrixObjectStore::new(test_options()).unwrap();
    let mut replicated = RaftBackedObjectStore::new(raft, store);
    replicated
        .propose_register_meta_coordinator_session("session-a", "meta-a", "127.0.0.1:9100", 100, 10)
        .unwrap();
    replicated
        .propose_configure_meta_shard(MetadataShard {
            shard_id: "objects-idem".to_string(),
            start_key: "object/owner-idem/".to_string(),
            end_key: "object/owner-idem0".to_string(),
            owner_node_id: "meta-a".to_string(),
            epoch: 1,
            draining: false,
        })
        .unwrap();
    let mutations = vec![MetadataMutation {
        key: "object/owner-idem/item".to_string().into(),
        value: "etag=owner-idem length=1".to_string(),
        expected_version: 0,
        delete: false,
    }];
    let first = replicated
        .propose_commit_owner_fenced_metadata_batch_idempotent(
            mutations.clone(),
            "meta-a",
            1,
            None,
            None,
            20,
            "raft-meta-owner-batch-a",
        )
        .unwrap();
    assert_eq!(
        first.content_type,
        "metaserver/idempotent-owner-fenced-batch"
    );
    assert_eq!(first.version, 1);
    assert_eq!(first.length, 0);
    let retry = replicated
        .propose_commit_owner_fenced_metadata_batch_idempotent(
            mutations.clone(),
            "meta-a",
            1,
            None,
            None,
            20,
            "raft-meta-owner-batch-a",
        )
        .unwrap();
    assert_eq!(
        retry.content_type,
        "metaserver/idempotent-owner-fenced-batch"
    );
    assert_eq!(retry.version, 1);
    assert_eq!(retry.length, 1);
    assert!(matches!(
        replicated.propose_commit_owner_fenced_metadata_batch_idempotent(
            vec![MetadataMutation {
                key: "object/owner-idem/item".to_string().into(),
                value: "changed".to_string(),
                expected_version: 0,
                delete: false,
            }],
            "meta-a",
            1,
            None,
            None,
            20,
            "raft-meta-owner-batch-a",
        ),
        Err(ObjectError::PreconditionFailed(_))
    ));
    assert_eq!(replicated.raft_commit_index(), 4);

    let mut follower = MatrixObjectStore::new(test_options()).unwrap();
    replicated.replay_into(&mut follower).unwrap();
    let record = follower.metadata_record("object/owner-idem/item").unwrap();
    assert_eq!(record.version, 1);
    assert_eq!(record.value, "etag=owner-idem length=1".into());
    let snapshot = follower.export_snapshot().unwrap();
    assert_eq!(snapshot.meta_snapshot.batch_request_receipts.len(), 1);
    let mut restored = MatrixObjectStore::new(test_options()).unwrap();
    restored.install_snapshot(snapshot).unwrap();
    let (records, restored_retry) = restored
        .commit_owner_fenced_metadata_batch_idempotent(
            mutations,
            "meta-a",
            1,
            None,
            None,
            20,
            "raft-meta-owner-batch-a",
        )
        .unwrap();
    assert!(restored_retry.deduped);
    assert_eq!(records[0].version, 1);
}

#[test]
fn raft_backed_store_replays_metaserver_tombstone_compaction() {
    let raft = InMemoryRustRaft::new(1).unwrap();
    let store = MatrixObjectStore::new(test_options()).unwrap();
    let mut replicated = RaftBackedObjectStore::new(raft, store);
    replicated
        .propose_begin_meta_transaction(
            "raft-tombstone-put",
            "writer-a",
            100,
            vec![MetadataMutation {
                key: "object/raft-tombstone/gone".to_string().into(),
                value: "gone".to_string(),
                expected_version: 0,
                delete: false,
            }],
            1,
        )
        .unwrap();
    replicated
        .propose_commit_meta_transaction("raft-tombstone-put", "writer-a", 2)
        .unwrap();
    replicated
        .propose_delete_meta_by_prefix("object/raft-tombstone/gone", 1, None, None, 3)
        .unwrap();
    let meta_key = "object/raft-tombstone/gone".to_string();
    let delete_change = replicated
        .store()
        .metadata_changes_after(0, 16)
        .into_iter()
        .find(|change| change.key == meta_key && change.deleted)
        .unwrap();
    replicated
        .propose_commit_meta_change_checkpoint(MetadataChangeCheckpoint {
            consumer_id: "raft-tombstone-consumer".to_string(),
            prefix: "object/raft-tombstone/".to_string(),
            after_change_sequence: delete_change.sequence,
            after_commit_index: delete_change.commit_index,
            update_time_ms: 4,
            owner: "metaserver-a".to_string(),
            note: "safe through delete".to_string(),
        })
        .unwrap();
    let compacted = replicated
        .propose_compact_metadata_tombstones("object/raft-tombstone/", None, 10, 0)
        .unwrap();
    assert_eq!(compacted.content_type, "metaserver/tombstone-compact");
    assert_eq!(compacted.version, 1);
    assert_eq!(replicated.raft_commit_index(), 5);
    assert!(replicated.store().metadata_record(&meta_key).is_err());

    let mut follower = MatrixObjectStore::new(test_options()).unwrap();
    replicated.replay_into(&mut follower).unwrap();
    assert!(follower.metadata_record(&meta_key).is_err());
    let report = follower
        .plan_metadata_tombstone_compaction("object/raft-tombstone/", None, 10, 0)
        .unwrap();
    assert_eq!(report.compacted_tombstone_count, 1);
    assert_eq!(follower.last_applied_index(), 5);
}

