#[test]
fn raft_backed_store_applies_prepared_chunk_trim_flow_control() {
    let raft = InMemoryRustRaft::new(1).unwrap();
    let store = MatrixObjectStore::new(test_options()).unwrap();
    let mut replicated = RaftBackedObjectStore::new(raft, store);
    let slab_id = SlabId {
        volume_id: 0,
        id: 7021,
    };
    replicated
        .propose_write_page_range_idempotent(
            slab_id,
            0,
            b"seed".to_vec(),
            "prepared-trim-flow-seed",
        )
        .unwrap();

    let stale_route_checksum = replicated
        .store()
        .page_service
        .route_control_proof()
        .state_checksum;
    replicated
        .propose_configure_page_route_qos(PageRouteQosConfig {
            window_ms: 30_000,
            max_read_ops_per_window: 100,
            max_read_bytes_per_window: 1024 * 1024,
            max_write_ops_per_window: 100,
            max_write_bytes_per_window: 1024 * 1024,
            max_discard_ops_per_window: 100,
            max_discard_bytes_per_window: 1024 * 1024,
        })
        .unwrap();
    let current_route_checksum = replicated
        .store()
        .page_service
        .route_control_proof()
        .state_checksum;
    assert_ne!(stale_route_checksum, current_route_checksum);
    assert!(matches!(
        replicated.prepare_configure_chunk_trim_flow_raft_entry_linearizable_fenced(
            7,
            21,
            1_234,
            Some(&stale_route_checksum),
        ),
        Err(ObjectError::PreconditionFailed(_))
    ));
    let prepared = replicated
        .prepare_configure_chunk_trim_flow_raft_entry_linearizable_fenced(
            7,
            21,
            1_234,
            Some(&current_route_checksum),
        )
        .unwrap();
    assert_eq!(prepared.expected_previous_commit_index, 2);
    assert_eq!(prepared.prepared_commit_index, 3);
    assert_eq!(prepared.rate_bytes_per_sec, 7);
    assert_eq!(prepared.burst_bytes, 21);
    assert_eq!(prepared.now_ms, 1_234);
    assert_eq!(
        prepared.route_control_proof.state_checksum,
        current_route_checksum
    );
    assert_eq!(
        prepared.expected_route_control_checksum,
        current_route_checksum
    );
    assert!(!prepared.before_page_service_fingerprint.is_empty());
    assert!(!prepared.after_page_service_fingerprint.is_empty());
    assert_ne!(
        prepared.before_page_service_fingerprint,
        prepared.after_page_service_fingerprint
    );
    assert!(!prepared.raft_entry_checksum.is_empty());

    let mut tampered = prepared.clone();
    tampered.burst_bytes = 22;
    assert!(matches!(
        replicated
            .store()
            .clone()
            .apply_command(ObjectCommand::ApplyPreparedChunkTrimFlow { prepared: tampered }),
        Err(ObjectError::Corruption(_))
    ));
    let mut stale_source = replicated.store().clone();
    stale_source
        .page_service
        .set_replica_frozen(0, true)
        .unwrap();
    assert!(matches!(
        stale_source.apply_prepared_chunk_trim_flow(prepared.clone()),
        Err(ObjectError::PreconditionFailed(_))
    ));

    let applied = replicated
        .propose_prepared_chunk_trim_flow_linearizable_fenced(
            prepared,
            Some(&current_route_checksum),
        )
        .unwrap();
    assert_eq!(applied.content_type, "chunkserver/prepared-trim-flow");
    assert_eq!(applied.object_id.key, "all_replicas");
    assert_eq!(applied.version, 7);
    assert_eq!(applied.length, 3);
    assert_eq!(applied.update_time_ms, 1_234);
    assert_eq!(replicated.raft_commit_index(), 3);

    let mut follower = MatrixObjectStore::new(test_options()).unwrap();
    replicated.replay_into(&mut follower).unwrap();
    assert_eq!(follower.last_applied_index(), 3);
    assert!(follower
        .page_service
        .replicas
        .iter()
        .all(|replica| replica.trim_flow_rate_bytes_per_sec() == 7));
    assert!(follower
        .page_service
        .replicas
        .iter()
        .all(|replica| replica.trim_flow_burst_bytes() == 21));
    assert!(follower
        .page_service
        .replicas
        .iter()
        .all(|replica| replica.trim_flow_available_bytes() == 21));
    let readiness = follower.page_storage_readiness(0, 0, 10);
    assert!(readiness
        .replica_readiness
        .iter()
        .all(|replica| replica.control_proof.state_format == "MOSRSCHUNKCONTROL12"));
    assert!(readiness
        .replica_readiness
        .iter()
        .all(|replica| replica.trim_flow_available_bytes == 21));
}

#[test]
fn raft_backed_store_replays_chunk_read_cache_configuration() {
    let raft = InMemoryRustRaft::new(1).unwrap();
    let store = MatrixObjectStore::new(test_options()).unwrap();
    let mut replicated = RaftBackedObjectStore::new(raft, store);
    let configured = replicated.propose_configure_chunk_read_cache(4).unwrap();
    assert_eq!(configured.content_type, "chunkserver/read-cache-config");
    assert_eq!(
        replicated.store().chunk_read_cache_max_bytes_per_replica(),
        4
    );
    assert!(replicated.store().read_cache_stats().max_bytes <= 12);

    let mut follower = MatrixObjectStore::new(test_options()).unwrap();
    replicated.replay_into(&mut follower).unwrap();
    assert_eq!(follower.chunk_read_cache_max_bytes_per_replica(), 4);
    assert!(follower.read_cache_stats().max_bytes <= 12);
    assert_eq!(follower.last_applied_index(), 1);

    let snapshot = replicated.store().export_snapshot().unwrap();
    assert_eq!(snapshot.chunk_read_cache_max_bytes_per_replica, 4);
    let mut restored = MatrixObjectStore::new(test_options()).unwrap();
    restored.install_snapshot(snapshot).unwrap();
    assert_eq!(restored.chunk_read_cache_max_bytes_per_replica(), 4);
    assert!(restored.read_cache_stats().max_bytes <= 12);
}

#[test]
fn raft_backed_object_chunk_cache_control_is_linearizable() {
    let raft = InMemoryRustRaft::new(1).unwrap();
    let store = MatrixObjectStore::new(test_options()).unwrap();
    let mut replicated = RaftBackedObjectStore::new(raft, store);
    replicated
        .propose(ObjectCommand::PutObject {
            bucket: "bucket".to_string(),
            key: "raft-cache-control".to_string(),
            data: b"abcdefghijkl".to_vec(),
            content_type: "text/plain".to_string(),
            update_time_ms: 2,
            options: PutOptions::default(),
        })
        .unwrap();
    let metadata = replicated
        .store()
        .head_object("bucket", "raft-cache-control")
        .unwrap();
    let chunk = replicated
        .store()
        .page_service
        .map_range(
            &metadata.extents[0].slab_id,
            metadata.extents[0].offset,
            4,
        )
        .unwrap()[0]
        .chunk_id
        .clone();
    let route_checksum = replicated
        .store()
        .page_service
        .route_control_proof()
        .state_checksum;

    assert!(matches!(
        replicated.configure_chunk_read_cache_control_with_read_proof_linearizable_fenced(
            8,
            Some("stale-route")
        ),
        Err(ObjectError::PreconditionFailed(_))
    ));
    let configured = replicated
        .configure_chunk_read_cache_control_with_read_proof_linearizable_fenced(
            8,
            Some(&route_checksum),
        )
        .unwrap();
    assert_eq!(configured.value.configured_chunk_endpoint_count, 3);
    assert_eq!(configured.value.remote_chunk_endpoint_count, 3);
    assert_eq!(configured.value.read_cache_max_bytes, 24);
    assert_eq!(configured.proof.control_kind, "block-route");
    assert_eq!(configured.proof.control_checksum, route_checksum);
    assert_eq!(replicated.raft_commit_index(), 1);

    let warmed = replicated
        .prewarm_chunk_read_cache_control_with_read_proof_linearizable_fenced(
            chunk.clone(),
            0,
            4,
            0,
            Some(&route_checksum),
        )
        .unwrap();
    assert_eq!(warmed.value.stats.contacted_chunk_endpoints, 3);
    assert!(warmed.value.stats.selected_bytes >= 4);
    assert!(warmed.value.selected_chunk_endpoint.is_some());

    let batch = replicated
        .prewarm_chunk_read_cache_control_batch_with_read_proof_linearizable_fenced(
            vec![
                ChunkReadCacheRange {
                    chunk_id: chunk.clone(),
                    offset: 0,
                    length: 2,
                },
                ChunkReadCacheRange {
                    chunk_id: chunk.clone(),
                    offset: 2,
                    length: 2,
                },
            ],
            0,
            Some(&route_checksum),
        )
        .unwrap();
    assert_eq!(batch.value.stats.contacted_chunk_endpoints, 3);
    assert!(batch.value.stats.selected_bytes >= 4);

    let invalidated = replicated
        .invalidate_chunk_read_cache_control_with_read_proof_linearizable_fenced(
            chunk,
            0,
            4,
            0,
            Some(&route_checksum),
        )
        .unwrap();
    assert!(invalidated.value.stats.invalidated_entries > 0);
    assert_eq!(invalidated.value.invalidated_chunk_endpoint_count, 3);

    let cleared = replicated
        .clear_chunk_read_cache_control_with_read_proof_linearizable_fenced(Some(&route_checksum))
        .unwrap();
    assert_eq!(cleared.value.cleared_chunk_endpoint_count, 3);
    assert_eq!(cleared.value.cleared_read_cache_bytes, 0);
    assert_eq!(replicated.raft_commit_index(), 1);
}

