#[test]
fn raft_backed_store_replays_idempotent_multipart_create() {
    let raft = InMemoryRustRaft::new(1).unwrap();
    let store = MatrixObjectStore::new(test_options()).unwrap();
    let mut replicated = RaftBackedObjectStore::new(raft, store);
    let route_checksum = replicated
        .store
        .page_service
        .route_control_proof()
        .state_checksum;
    let report = replicated
        .propose_create_multipart_upload_idempotent_with_route_report_linearizable_fenced(
            "mpu-idem",
            "bucket",
            "large",
            "application/octet-stream",
            PutOptions::default(),
            10,
            "multipart-create-idem-a",
            &route_checksum,
        )
        .unwrap();
    assert_eq!(report.upload.upload_id, "mpu-idem");
    assert_eq!(
        report.upload.create_idempotency_key.as_deref(),
        Some("multipart-create-idem-a")
    );
    assert_eq!(replicated.raft_commit_index(), 1);
    let retry = replicated
        .propose_create_multipart_upload_idempotent_with_route_report_linearizable_fenced(
            "mpu-idem",
            "bucket",
            "large",
            "application/octet-stream",
            PutOptions::default(),
            10,
            "multipart-create-idem-a",
            &route_checksum,
        )
        .unwrap();
    assert_eq!(retry.upload, report.upload);
    assert_eq!(replicated.raft_commit_index(), 1);
    assert!(matches!(
        replicated
            .propose_create_multipart_upload_idempotent_with_route_report_linearizable_fenced(
                "mpu-idem",
                "bucket",
                "large",
                "application/octet-stream",
                PutOptions::default(),
                10,
                "multipart-create-idem-b",
                &route_checksum,
            ),
        Err(ObjectError::PreconditionFailed(_))
    ));

    let mut follower = MatrixObjectStore::new(test_options()).unwrap();
    replicated.replay_into(&mut follower).unwrap();
    let replayed = follower.multipart_upload("mpu-idem").unwrap();
    assert_eq!(
        replayed.create_idempotency_key.as_deref(),
        Some("multipart-create-idem-a")
    );
    let snapshot = follower.export_snapshot().unwrap();
    let restored = StoreSnapshot::from_bytes(&snapshot.to_bytes().unwrap()).unwrap();
    assert_eq!(
        restored
            .multipart_uploads
            .get("mpu-idem")
            .unwrap()
            .create_idempotency_key
            .as_deref(),
        Some("multipart-create-idem-a")
    );
}

